  const majorDocumentUrls=new Map();
  function getMajorPdfUrl(document){
    if(majorDocumentUrls.has(document.name))return majorDocumentUrls.get(document.name);
    const raw=atob(document.data),chunks=[],limit=32768;
    for(let i=0;i<raw.length;i+=limit){
      const part=raw.slice(i,i+limit),bytes=new Uint8Array(part.length);
      for(let j=0;j<part.length;j++)bytes[j]=part.charCodeAt(j);
      chunks.push(bytes);
    }
    const url=URL.createObjectURL(new Blob(chunks,{type:'application/pdf'}));
    majorDocumentUrls.set(document.name,url);
    return url;
  }
